-- 九霄问道 SQL262 · V2.2.0 CACHE134
-- 九霄游历 V1：300条正式故事 / 9境界差异 / 8区域 / 游历调查追踪回访 / 妖兽战斗 / 受伤失败 / 跨境界因果 / NPC联动 / 游历志
-- 同步修复天道人物本地人格兜底：禁止客服腔、系统腔，直接以NPC第一人称回应。
-- 基线要求：SQL261 ONLINE / SQL261_GATE_PASSED
-- 成功后：SQL262 ONLINE / NEXT SQL263

begin;

-- ==================== PRECHECK ====================
do $precheck$
begin
  if to_regclass('public.player_characters') is null or to_regclass('public.realm_stages') is null or to_regclass('public.realms') is null then raise exception 'SQL262_PRECHECK_REALM_CORE_MISSING'; end if;
  if to_regprocedure('public.tianxu_active_character_v255()') is null then raise exception 'SQL262_PRECHECK_ACTIVE_CHARACTER_MISSING'; end if;
  if to_regprocedure('public.tianxu_inventory_adjust_v255(uuid,text,bigint)') is null then raise exception 'SQL262_PRECHECK_INVENTORY_HELPER_MISSING'; end if;
  if to_regclass('public.tiandao_npcs_v259') is null or to_regclass('public.tiandao_relations_v259') is null then raise exception 'SQL262_PRECHECK_TIANDAO_PEOPLE_MISSING'; end if;
  if to_regprocedure('public.tiandao_ensure_relation_v259(uuid,uuid,text)') is null then raise exception 'SQL262_PRECHECK_TIANDAO_RELATION_HELPER_MISSING'; end if;
  if to_regprocedure('public.tiandao_add_memory_v259(uuid,uuid,text,text,integer,boolean,jsonb)') is null then raise exception 'SQL262_PRECHECK_TIANDAO_MEMORY_HELPER_MISSING'; end if;
  if to_regprocedure('public.server_personality_v1(jsonb)') is null then raise exception 'SQL262_PRECHECK_SQL261_FALLBACK_MISSING'; end if;
  if pg_get_function_result(to_regprocedure('public.tiandao_add_memory_v259(uuid,uuid,text,text,integer,boolean,jsonb)'))<>'void' then raise exception 'SQL262_PRECHECK_MEMORY_ABI_NOT_VOID'; end if;
end
$precheck$;

-- ==================== TABLES ====================
create table if not exists public.exploration_settings_v262(
  singleton_id smallint primary key default 1 check(singleton_id=1),
  enabled boolean not null default true,
  daily_runs integer not null default 3 check(daily_runs between 1 and 30),
  max_active_runs integer not null default 1 check(max_active_runs between 1 and 3),
  defeat_loot_keep_percent integer not null default 50 check(defeat_loot_keep_percent between 0 and 100),
  minor_injury_minutes integer not null default 30 check(minor_injury_minutes between 5 and 1440),
  major_injury_minutes integer not null default 120 check(major_injury_minutes between 10 and 2880),
  repeatable_cooldown_hours integer not null default 168 check(repeatable_cooldown_hours between 24 and 2160),
  updated_at timestamptz not null default clock_timestamp()
);
insert into public.exploration_settings_v262(singleton_id) values(1) on conflict(singleton_id) do nothing;

create table if not exists public.exploration_regions_v262(
  region_code text primary key,
  name text not null,
  min_major_order integer not null check(min_major_order between 1 and 9),
  description text not null,
  enabled boolean not null default true
);
insert into public.exploration_regions_v262(region_code,name,min_major_order,description,enabled) values
('qingshan','青云山',1,'山林、溪谷与旧修士足迹交叠的入道之地。',true),
('luoxia','落霞谷',1,'黄昏霞光终年不散，谷中残阵与药田众多。',true),
('yunhai','云海渡口',1,'云舟、商旅、散修与消息汇聚之地。',true),
('heishui','黑水泽',2,'水泽阴湿，妖兽、沉船和地下水脉彼此纠缠。',true),
('chiyuan','赤渊荒原',3,'火脉纵横的荒原，旧战场与妖族领地犬牙交错。',true),
('cangming','沧溟古海',4,'群岛与深海遗迹并存，潮汐常带出失落旧物。',true),
('taixu','太虚裂境',6,'空间并不稳定，裂隙背后藏着不属于现世的区域。',true),
('wujitian','无极天域',7,'高阶修士与古老势力才有资格长期踏足的天外区域。',true)
on conflict(region_code) do update set name=excluded.name,min_major_order=excluded.min_major_order,description=excluded.description,enabled=true;

create table if not exists public.exploration_story_defs_v262(
  story_code text primary key,
  title text not null,
  story_type text not null,
  choice_profile text not null,
  rarity text not null check(rarity in('common','uncommon','rare','epic')),
  region_code text not null references public.exploration_regions_v262(region_code),
  min_major_order integer not null check(min_major_order between 1 and 9),
  max_major_order integer not null check(max_major_order between 1 and 9),
  stage_count integer not null check(stage_count between 3 and 10),
  stage_gates integer[] not null,
  is_cross_realm boolean not null default false,
  repeatable boolean not null default false,
  weight integer not null default 100 check(weight between 1 and 1000),
  danger_level integer not null default 1 check(danger_level between 0 and 5),
  npc_code text,
  creature_code text,
  synopsis text not null,
  stage_texts jsonb not null default '[]'::jsonb,
  tags jsonb not null default '[]'::jsonb,
  enabled boolean not null default true,
  created_at timestamptz not null default clock_timestamp()
);

insert into public.exploration_story_defs_v262(story_code,title,story_type,choice_profile,rarity,region_code,min_major_order,max_major_order,stage_count,stage_gates,is_cross_realm,repeatable,weight,danger_level,npc_code,creature_code,synopsis,stage_texts,tags,enabled) values
('jxexp_r1_01','青云山·受伤青狼：求助','beast','beast','common','qingshan',1,1,5,ARRAY[1,1,1,1,1]::integer[],false,true,100,2,null,'beast_1_01','青云山出现了与“受伤青狼”有关的求助迹象；以炼气境界来看，你已经有资格靠近，但并不代表没有风险。','["青云山出现了与“受伤青狼”有关的求助迹象；以炼气境界来看，你已经有资格靠近，但并不代表没有风险。你先发现了它留下的痕迹，而不是直接看见它。","围绕“青云山·受伤青狼：求助”，那头生灵已经察觉到你，攻击、观察、救助或退让都还有余地。","围绕“青云山·受伤青狼：求助”，你开始明白它为何出现在这里，杀与不杀会留下不同后果。","围绕“青云山·受伤青狼：求助”，这次人与妖兽的遭遇到了结果，无论胜负都会被此地记住。","围绕“青云山·受伤青狼：求助”，这次人与妖兽的遭遇到了结果，无论胜负都会被此地记住。"]'::jsonb,'["炼气","青云山","beast"]'::jsonb,true),
('jxexp_r1_02','落霞谷·受伤青狼：夜访','resource','resource','common','luoxia',1,1,4,ARRAY[1,1,1,1]::integer[],false,false,100,2,null,null,'落霞谷出现了与“受伤青狼”有关的夜访迹象；以炼气境界来看，你已经有资格靠近，但并不代表没有风险。','["落霞谷出现了与“受伤青狼”有关的夜访迹象；以炼气境界来看，你已经有资格靠近，但并不代表没有风险。表面的灵气波动说明这里可能有可取之物。","围绕“落霞谷·受伤青狼：夜访”，真正靠近后，你发现采与不采、取多少，本身就是选择。","围绕“落霞谷·受伤青狼：夜访”，资源背后还有来源与守护者，贪多可能引来风险。","围绕“落霞谷·受伤青狼：夜访”，你决定如何带走收获，也决定这个地方下次回来还剩什么。"]'::jsonb,'["炼气","落霞谷","resource"]'::jsonb,true),
('jxexp_r1_03','云海渡口·无名石碑：守候','mystery','mystery','common','yunhai',1,1,4,ARRAY[1,1,1,1]::integer[],false,false,100,4,null,null,'云海渡口出现了与“无名石碑”有关的守候迹象；以炼气境界来看，你已经有资格靠近，但并不代表没有风险。','["云海渡口出现了与“无名石碑”有关的守候迹象；以炼气境界来看，你已经有资格靠近，但并不代表没有风险。一处不合常理的细节让你停下脚步。","围绕“云海渡口·无名石碑：守候”，你越观察，越发现表象之下还藏着另一层原因。","围绕“云海渡口·无名石碑：守候”，线索已经足够让你作出判断，但继续深挖也意味着承担风险。","围绕“云海渡口·无名石碑：守候”，谜团得到一个阶段性的答案，并留下了值得以后回访的痕迹。"]'::jsonb,'["炼气","云海渡口","mystery"]'::jsonb,true),
('jxexp_r1_04','青云山·洛微尘：初见','npc','npc','common','qingshan',1,1,5,ARRAY[1,1,1,1,1]::integer[],false,false,100,4,'romance_luo_weichen',null,'你在青云山意外遇见洛微尘。TA正在处理“失路采药人”相关的事情，并没有专门等你。','["你在青云山意外遇见洛微尘。TA正在处理“失路采药人”相关的事情，并没有专门等你。你在本不该遇见熟人的地方看见了一个身影。","围绕“青云山·洛微尘：初见”，对方有自己的目的，并不是站在这里等你触发剧情。","围绕“青云山·洛微尘：初见”，你是否介入，会被TA记进自己的经历。","围绕“青云山·洛微尘：初见”，事情暂时告一段落，你们之间多了一段只发生在旅途中的往事。","围绕“青云山·洛微尘：初见”，事情暂时告一段落，你们之间多了一段只发生在旅途中的往事。"]'::jsonb,'["炼气","青云山","npc"]'::jsonb,true),
('jxexp_r1_05','落霞谷·失路采药人：暗响','trace','trace','common','luoxia',1,1,4,ARRAY[1,1,1,1]::integer[],false,true,100,1,null,null,'落霞谷出现了与“失路采药人”有关的暗响迹象；以炼气境界来看，你已经有资格靠近，但并不代表没有风险。','["落霞谷出现了与“失路采药人”有关的暗响迹象；以炼气境界来看，你已经有资格靠近，但并不代表没有风险。一点不起眼的痕迹让你意识到附近还有别的事。","围绕“落霞谷·失路采药人：暗响”，追踪让线索从零散变得连贯，但也把你带向更深处。","围绕“落霞谷·失路采药人：暗响”，目标终于露出轮廓，你可以继续逼近，也可以保留情报离开。","围绕“落霞谷·失路采药人：暗响”，追踪得到结果：它可能是猎物、人物、遗迹，也可能是一场误判。"]'::jsonb,'["炼气","落霞谷","trace"]'::jsonb,true),
