create table if not exists public.exploration_story_progress_v262(
  character_id uuid not null references public.player_characters(id) on delete cascade,
  story_code text not null references public.exploration_story_defs_v262(story_code),
  current_stage integer not null default 1,
  status text not null default 'active' check(status in('active','paused','completed')),
  next_realm_order integer,
  branch_flags jsonb not null default '{}'::jsonb,
  times_seen integer not null default 0,
  times_completed integer not null default 0,
  last_result text not null default '',
  first_seen_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  primary key(character_id,story_code)
);

create table if not exists public.exploration_runs_v262(
  id uuid primary key default gen_random_uuid(),
  character_id uuid not null references public.player_characters(id) on delete cascade,
  story_code text not null references public.exploration_story_defs_v262(story_code),
  region_code text not null references public.exploration_regions_v262(region_code),
  mode text not null default 'wander' check(mode in('wander','investigate','track','revisit')),
  stage integer not null default 1,
  status text not null default 'active' check(status in('active','completed','failed','retreated','paused')),
  pending_spirit_stones bigint not null default 0 check(pending_spirit_stones>=0),
  insight_gained integer not null default 0 check(insight_gained>=0),
  current_node jsonb not null default '{}'::jsonb,
  last_battle jsonb not null default '{}'::jsonb,
  result_summary text not null default '',
  started_at timestamptz not null default clock_timestamp(),
  updated_at timestamptz not null default clock_timestamp(),
  resolved_at timestamptz
);
create unique index if not exists exploration_one_active_run_v262 on public.exploration_runs_v262(character_id) where status='active';
create index if not exists exploration_runs_daily_v262 on public.exploration_runs_v262(character_id,started_at desc);

create table if not exists public.exploration_profile_v262(
  character_id uuid primary key references public.player_characters(id) on delete cascade,
  insight integer not null default 0 check(insight>=0),
  runs_started integer not null default 0 check(runs_started>=0),
  runs_completed integer not null default 0 check(runs_completed>=0),
  battles_won integer not null default 0 check(battles_won>=0),
  battles_lost integer not null default 0 check(battles_lost>=0),
  discoveries integer not null default 0 check(discoveries>=0),
  updated_at timestamptz not null default clock_timestamp()
);

create table if not exists public.exploration_discoveries_v262(
  character_id uuid not null references public.player_characters(id) on delete cascade,
  discovery_code text not null,
  region_code text not null references public.exploration_regions_v262(region_code),
  story_code text references public.exploration_story_defs_v262(story_code),
  title text not null,
  detail text not null,
  times_seen integer not null default 1,
  first_seen_at timestamptz not null default clock_timestamp(),
  last_seen_at timestamptz not null default clock_timestamp(),
  primary key(character_id,discovery_code)
);

create table if not exists public.exploration_journal_v262(
  id bigint generated always as identity primary key,
  character_id uuid not null references public.player_characters(id) on delete cascade,
  kind text not null,
  region_code text,
  story_code text,
  title text not null,
  content text not null,
  importance integer not null default 1 check(importance between 1 and 5),
  metadata jsonb not null default '{}'::jsonb,
  created_at timestamptz not null default clock_timestamp()
);
create index if not exists exploration_journal_character_v262 on public.exploration_journal_v262(character_id,created_at desc);

create table if not exists public.exploration_injury_v262(
  character_id uuid primary key references public.player_characters(id) on delete cascade,
  severity text not null check(severity in('minor','major')),
  label text not null,
  detail text not null,
  expires_at timestamptz not null,
  updated_at timestamptz not null default clock_timestamp()
);

create table if not exists public.exploration_region_state_v262(
  character_id uuid not null references public.player_characters(id) on delete cascade,
  region_code text not null references public.exploration_regions_v262(region_code),
  familiarity integer not null default 0 check(familiarity between 0 and 100),
  beast_pressure integer not null default 0 check(beast_pressure between -100 and 100),
  mercy_marks integer not null default 0 check(mercy_marks>=0),
  kill_marks integer not null default 0 check(kill_marks>=0),
  updated_at timestamptz not null default clock_timestamp(),
  primary key(character_id,region_code)
);

-- 所有内部表不直接暴露给客户端，只经RPC。
revoke all on public.exploration_settings_v262,public.exploration_regions_v262,public.exploration_story_defs_v262,public.exploration_story_progress_v262,public.exploration_runs_v262,public.exploration_profile_v262,public.exploration_discoveries_v262,public.exploration_journal_v262,public.exploration_injury_v262,public.exploration_region_state_v262 from public,anon,authenticated;

-- ==================== HELPERS ====================
create or replace function public.exploration_realm_theme_v262(p_major integer)
returns text language sql immutable set search_path='' as $$
select case p_major
 when 1 then '生存与认识世界：观察、采集、判断能不能打。'
 when 2 then '主动冒险：追踪、探洞、找灵脉与妖兽巢穴。'
 when 3 then '介入世界：破阵、交涉、面对有灵智的妖兽与地方冲突。'
 when 4 then '改变地区：大型遗迹、妖潮、封印与区域事件。'
 when 5 then '理解天地：法则痕迹、因果、旧历史与异象。'
 when 6 then '探索空间：虚空裂隙、空间夹层、失落洞天。'
 when 7 then '组织远征：同行者、分工、队伍选择与大型危险。'
 when 8 then '左右世界：不可轻易撤销的区域与世界级选择。'
 when 9 then '收束一生：旧缘、承诺、仇怨与渡劫前未了因果。'
 else '尚未踏入真正的九霄游历。' end;
$$;

create or replace function public.exploration_choice_set_v262(p_profile text,p_stage integer,p_final boolean default false)
returns jsonb language plpgsql immutable set search_path='' as $$
begin
  if p_final then
    return jsonb_build_array(
      jsonb_build_object('code','resolve_spare','label','留下余地','hint','少拿一些眼前收益，保留长期后果'),
      jsonb_build_object('code','resolve_claim','label','取走眼前所得','hint','收益更高，但可能留下更重痕迹'),
      jsonb_build_object('code','resolve_leave','label','让事情到此为止','hint','安全收束，不再强求')
    );
  end if;
  if p_profile='beast' then return jsonb_build_array(
    jsonb_build_object('code','observe','label','先观察','hint','先判断它为何出现在这里'),
    jsonb_build_object('code','fight','label','主动出手','hint','进入真实胜负判定，失败会受伤并损失本次旅囊'),
    jsonb_build_object('code','help','label','尝试救助/安抚','hint','对受伤或护崽的妖兽可能产生长期后果'),
    jsonb_build_object('code','retreat','label','退开','hint','安全结束本次游历')
  );
  elsif p_profile='resource' then return jsonb_build_array(
    jsonb_build_object('code','harvest_careful','label','只取合适的','hint','收益较稳，也给地点留下恢复空间'),
    jsonb_build_object('code','harvest_greedy','label','尽量全部带走','hint','眼前收益高，但风险和地区痕迹更重'),
    jsonb_build_object('code','observe','label','先看清来源','hint','可能发现资源背后的线索'),
    jsonb_build_object('code','retreat','label','不取','hint','不承担风险')
  );
  elsif p_profile='npc' then return jsonb_build_array(
    jsonb_build_object('code','greet','label','过去打招呼','hint','让这次偶遇真正进入人物记忆'),
    jsonb_build_object('code','help','label','问TA需不需要帮忙','hint','介入TA正在做的事'),
    jsonb_build_object('code','observe','label','先看看发生了什么','hint','不贸然打断TA'),
    jsonb_build_object('code','retreat','label','不去打扰','hint','让TA继续自己的生活')
  );
  elsif p_profile in('trace','mystery') then return jsonb_build_array(
    jsonb_build_object('code','investigate','label','仔细调查','hint','提升见闻，并可能留下可回访发现'),
    jsonb_build_object('code','track','label','沿线索追下去','hint','更快接近真相，也更容易进入危险'),
    jsonb_build_object('code','record','label','先记录下来','hint','保守获得情报，之后可回访'),
    jsonb_build_object('code','retreat','label','离开','hint','安全结束')
  );
  elsif p_profile in('ruin','void') then return jsonb_build_array(
    jsonb_build_object('code','investigate','label','按痕迹慢慢查','hint','稳妥推进'),
    jsonb_build_object('code','force','label','强行深入','hint','推进更快，但可能触发机关或空间风险'),
    jsonb_build_object('code','record','label','记下坐标与结构','hint','形成长期发现'),
    jsonb_build_object('code','retreat','label','原路退回','hint','带着已有收获离开')
  );
  elsif p_profile in('conflict','region','world_choice','expedition') then return jsonb_build_array(
    jsonb_build_object('code','mediate','label','介入并听双方说法','hint','可能影响人物或地区状态'),
    jsonb_build_object('code','help','label','明确帮一方','hint','更快改变局势，也会留下立场'),
    jsonb_build_object('code','observe','label','先旁观','hint','少承担风险，但可能错过介入时机'),
    jsonb_build_object('code','retreat','label','不卷进去','hint','让事情按自己的方向发展')
  );
  else return jsonb_build_array(
    jsonb_build_object('code','comprehend','label','静下心感悟','hint','更偏向见闻、法则与长期理解'),
    jsonb_build_object('code','investigate','label','继续查证','hint','把抽象线索变得具体'),
    jsonb_build_object('code','record','label','先记在游历志里','hint','保留后续回访可能'),
    jsonb_build_object('code','retreat','label','暂且离开','hint','安全结束')
  ); end if;
end $$;

create or replace function public.exploration_make_node_v262(p_story_code text,p_stage integer)
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare d public.exploration_story_defs_v262%rowtype;r public.exploration_regions_v262%rowtype;v_text text;v_final boolean;
begin
  select * into d from public.exploration_story_defs_v262 where story_code=p_story_code and enabled;
  if d.story_code is null then raise exception 'EXPLORATION_STORY_NOT_FOUND'; end if;
  select * into r from public.exploration_regions_v262 where region_code=d.region_code;
  v_final:=p_stage>=d.stage_count;
  v_text:=coalesce(d.stage_texts->>(greatest(1,p_stage)-1),d.synopsis);
  return jsonb_build_object(
    'story_code',d.story_code,'title',d.title,'story_type',d.story_type,'rarity',d.rarity,'region_code',d.region_code,'region_name',r.name,
    'stage',p_stage,'stage_count',d.stage_count,'is_cross_realm',d.is_cross_realm,'danger_level',d.danger_level,'npc_code',d.npc_code,'creature_code',d.creature_code,
    'description',v_text,'choices',public.exploration_choice_set_v262(d.choice_profile,p_stage,v_final)
  );
end $$;

create or replace function public.exploration_context_v262()
returns jsonb language plpgsql stable security definer set search_path='' as $$
declare v_char uuid:=public.tianxu_active_character_v255();v jsonb;
begin
  select jsonb_build_object('character_id',pc.id,'name',pc.name,'realm_code',r.code,'realm_name',r.name,'major_order',r.major_order,'stage_name',rs.stage_name,'minor_level',rs.minor_level)
  into v from public.player_characters pc join public.realm_stages rs on rs.id=pc.realm_stage_id join public.realms r on r.id=rs.realm_id where pc.id=v_char;
  if v is null then raise exception 'EXPLORATION_CHARACTER_REALM_NOT_FOUND';end if;
  return v;
end $$;

create or replace function public.exploration_record_discovery_v262(p_character uuid,p_region text,p_story text,p_code text,p_title text,p_detail text)
returns boolean language plpgsql security definer set search_path='' as $$
declare v_new boolean:=false;
begin
  insert into public.exploration_discoveries_v262(character_id,discovery_code,region_code,story_code,title,detail)
  values(p_character,left(p_code,160),p_region,p_story,left(p_title,180),left(p_detail,800))
  on conflict(character_id,discovery_code) do update set times_seen=public.exploration_discoveries_v262.times_seen+1,last_seen_at=clock_timestamp(),detail=excluded.detail
  returning (times_seen=1) into v_new;
  if v_new then
    insert into public.exploration_profile_v262(character_id,discoveries) values(p_character,1)
    on conflict(character_id) do update set discoveries=public.exploration_profile_v262.discoveries+1,updated_at=clock_timestamp();
  end if;
  return coalesce(v_new,false);
end $$;

create or replace function public.exploration_touch_npc_v262(p_character uuid,p_story public.exploration_story_defs_v262,p_choice text,p_summary text)
returns void language plpgsql security definer set search_path='' as $$
declare v_npc uuid;v_da int:=0;v_dt int:=0;v_di int:=0;v_dres int:=0;
begin
  if coalesce(p_story.npc_code,'')='' then return;end if;
  select id into v_npc from public.tiandao_npcs_v259 where npc_code=p_story.npc_code and enabled;
  if v_npc is null then return;end if;
  perform public.tiandao_ensure_relation_v259(p_character,v_npc,'acquainted');
  if p_choice='help' then v_da:=1;v_dt:=2;v_di:=1;v_dres:=2;
  elsif p_choice='greet' then v_da:=1;v_dt:=1;
  elsif p_choice='mediate' then v_dt:=1;v_dres:=2;
  elsif p_choice='resolve_spare' then v_dt:=1;v_di:=1;v_dres:=2;
  end if;
  update public.tiandao_relations_v259 set affinity=least(100,affinity+v_da),trust=least(100,trust+v_dt),intimacy=least(100,intimacy+v_di),respect=least(100,respect+v_dres),interaction_count=interaction_count+1,last_interaction_at=clock_timestamp(),last_action='exploration:'||p_choice,latest_rumor=left(p_summary,500),current_status='你们在九霄游历途中有过一段真实的共同经历。',updated_at=clock_timestamp() where character_id=p_character and npc_id=v_npc;
  perform public.tiandao_add_memory_v259(p_character,v_npc,'exploration',left(p_summary,700),3,true,jsonb_build_object('story_code',p_story.story_code,'choice',p_choice));
end $$;

-- ==================== PLAYER RPCS ====================
create or replace function public.get_exploration_hub_v262()
returns jsonb language plpgsql security definer set search_path='' as $$
declare c jsonb:=public.exploration_context_v262();v_char uuid:=(c->>'character_id')::uuid;v_major int:=(c->>'major_order')::int;s public.exploration_settings_v262%rowtype;v_regions jsonb;v_run jsonb;v_discoveries jsonb;v_journal jsonb;v_profile jsonb;v_injury jsonb;v_used int;
begin
  select * into s from public.exploration_settings_v262 where singleton_id=1;
  delete from public.exploration_injury_v262 where character_id=v_char and expires_at<=clock_timestamp();
  insert into public.exploration_profile_v262(character_id) values(v_char) on conflict(character_id) do nothing;
  select count(*) into v_used from public.exploration_runs_v262 where character_id=v_char and started_at>=date_trunc('day',clock_timestamp());
  select coalesce(jsonb_agg(jsonb_build_object(
    'region_code',r.region_code,'name',r.name,'description',r.description,'min_major_order',r.min_major_order,'unlocked',(v_major>=r.min_major_order),
    'unseen',(select count(*) from public.exploration_story_defs_v262 d left join public.exploration_story_progress_v262 p on p.character_id=v_char and p.story_code=d.story_code where d.region_code=r.region_code and d.enabled and d.min_major_order<=v_major and d.max_major_order>=v_major and (p.story_code is null or (p.status='paused' and coalesce(p.next_realm_order,1)<=v_major) or (d.repeatable and p.updated_at<=clock_timestamp()-make_interval(hours=>s.repeatable_cooldown_hours)))),
    'familiarity',coalesce(rs.familiarity,0),'beast_pressure',coalesce(rs.beast_pressure,0)
  ) order by r.min_major_order,r.name),'[]'::jsonb) into v_regions
  from public.exploration_regions_v262 r left join public.exploration_region_state_v262 rs on rs.character_id=v_char and rs.region_code=r.region_code where r.enabled;
  select jsonb_build_object('run_id',x.id,'story_code',x.story_code,'region_code',x.region_code,'mode',x.mode,'stage',x.stage,'status',x.status,'pending_spirit_stones',x.pending_spirit_stones,'insight_gained',x.insight_gained,'node',x.current_node,'last_battle',x.last_battle,'started_at',x.started_at) into v_run from public.exploration_runs_v262 x where x.character_id=v_char and x.status='active' order by x.started_at desc limit 1;
  select coalesce(jsonb_agg(jsonb_build_object('code',d.discovery_code,'region_code',d.region_code,'region_name',r.name,'title',d.title,'detail',d.detail,'times_seen',d.times_seen,'first_seen_at',d.first_seen_at,'last_seen_at',d.last_seen_at) order by d.last_seen_at desc),'[]'::jsonb) into v_discoveries from (select * from public.exploration_discoveries_v262 where character_id=v_char order by last_seen_at desc limit 30) d left join public.exploration_regions_v262 r on r.region_code=d.region_code;
  select coalesce(jsonb_agg(jsonb_build_object('id',j.id,'kind',j.kind,'region_code',j.region_code,'story_code',j.story_code,'title',j.title,'content',j.content,'importance',j.importance,'created_at',j.created_at) order by j.created_at desc),'[]'::jsonb) into v_journal from (select * from public.exploration_journal_v262 where character_id=v_char order by created_at desc limit 40) j;
  select to_jsonb(p) into v_profile from public.exploration_profile_v262 p where character_id=v_char;
  select jsonb_build_object('severity',i.severity,'label',i.label,'detail',i.detail,'expires_at',i.expires_at) into v_injury from public.exploration_injury_v262 i where character_id=v_char and i.expires_at>clock_timestamp();
  return jsonb_build_object('status',case when s.enabled then 'ok' else 'disabled' end,'build','JIUXIAO_EXPLORATION_V262','character',c,'realm_theme',public.exploration_realm_theme_v262(v_major),'daily_used',v_used,'daily_limit',s.daily_runs,'daily_remaining',greatest(0,s.daily_runs-v_used),'regions',v_regions,'active_run',v_run,'discoveries',v_discoveries,'journal',v_journal,'profile',coalesce(v_profile,'{}'::jsonb),'injury',v_injury,'story_total',(select count(*) from public.exploration_story_defs_v262 where enabled),'cross_realm_total',(select count(*) from public.exploration_story_defs_v262 where enabled and is_cross_realm));
end $$;

create or replace function public.exploration_start_v262(p_region_code text,p_mode text default 'wander')
returns jsonb language plpgsql security definer set search_path='' as $$
declare c jsonb:=public.exploration_context_v262();v_char uuid:=(c->>'character_id')::uuid;v_major int:=(c->>'major_order')::int;s public.exploration_settings_v262%rowtype;r public.exploration_regions_v262%rowtype;d public.exploration_story_defs_v262%rowtype;p public.exploration_story_progress_v262%rowtype;v_run public.exploration_runs_v262%rowtype;v_used int;v_stage int:=1;v_node jsonb;
begin
  select * into s from public.exploration_settings_v262 where singleton_id=1;if not s.enabled then raise exception 'EXPLORATION_DISABLED';end if;
  p_mode:=lower(coalesce(nullif(trim(p_mode),''),'wander'));if p_mode not in('wander','investigate','track','revisit') then raise exception 'EXPLORATION_MODE_INVALID';end if;
  select * into r from public.exploration_regions_v262 where region_code=p_region_code and enabled;if r.region_code is null then raise exception 'EXPLORATION_REGION_NOT_FOUND';end if;if v_major<r.min_major_order then raise exception 'EXPLORATION_REGION_REALM_LOCKED';end if;
  select * into v_run from public.exploration_runs_v262 where character_id=v_char and status='active' order by started_at desc limit 1;if v_run.id is not null then return jsonb_build_object('status','active_exists','run',jsonb_build_object('run_id',v_run.id,'node',v_run.current_node,'pending_spirit_stones',v_run.pending_spirit_stones,'insight_gained',v_run.insight_gained));end if;
  if exists(select 1 from public.exploration_injury_v262 where character_id=v_char and severity='major' and expires_at>clock_timestamp()) then raise exception 'EXPLORATION_MAJOR_INJURY_REST_REQUIRED';end if;
  select count(*) into v_used from public.exploration_runs_v262 where character_id=v_char and started_at>=date_trunc('day',clock_timestamp());if v_used>=s.daily_runs then raise exception 'EXPLORATION_DAILY_LIMIT';end if;
  select d0.* into d from public.exploration_story_defs_v262 d0 left join public.exploration_story_progress_v262 p0 on p0.character_id=v_char and p0.story_code=d0.story_code
  where d0.enabled and d0.region_code=p_region_code and d0.min_major_order<=v_major and d0.max_major_order>=v_major
    and (p0.story_code is null or (d0.repeatable and p0.updated_at<=clock_timestamp()-make_interval(hours=>s.repeatable_cooldown_hours)) or (p0.status='paused' and coalesce(p0.next_realm_order,1)<=v_major))
    and (p_mode='wander' or (p_mode='investigate' and d0.story_type in('mystery','ruin','phenomenon','legacy','void')) or (p_mode='track' and d0.story_type in('beast','trace','conflict')) or (p_mode='revisit' and p0.story_code is not null))
  order by case when p0.story_code is null then 0 else 1 end, case d0.rarity when 'epic' then 3 when 'rare' then 2 when 'uncommon' then 1 else 0 end + random()*5 desc, d0.weight*random() desc limit 1;
  if d.story_code is null and p_mode<>'wander' then return public.exploration_start_v262(p_region_code,'wander');end if;
  if d.story_code is null then raise exception 'EXPLORATION_REGION_STORIES_EXHAUSTED';end if;
  select * into p from public.exploration_story_progress_v262 where character_id=v_char and story_code=d.story_code;
  if p.story_code is not null then if d.repeatable and p.status='completed' then v_stage:=1;else v_stage:=greatest(1,least(d.stage_count,p.current_stage));end if;end if;
  if d.stage_gates[v_stage]>v_major then raise exception 'EXPLORATION_STORY_REALM_GATE';end if;
  v_node:=public.exploration_make_node_v262(d.story_code,v_stage);
  insert into public.exploration_runs_v262(character_id,story_code,region_code,mode,stage,current_node) values(v_char,d.story_code,d.region_code,p_mode,v_stage,v_node) returning * into v_run;
  insert into public.exploration_story_progress_v262(character_id,story_code,current_stage,status,times_seen,updated_at) values(v_char,d.story_code,v_stage,'active',1,clock_timestamp()) on conflict(character_id,story_code) do update set current_stage=excluded.current_stage,status='active',next_realm_order=null,times_seen=public.exploration_story_progress_v262.times_seen+1,updated_at=clock_timestamp();
  insert into public.exploration_profile_v262(character_id,runs_started) values(v_char,1) on conflict(character_id) do update set runs_started=public.exploration_profile_v262.runs_started+1,updated_at=clock_timestamp();
  insert into public.exploration_region_state_v262(character_id,region_code,familiarity) values(v_char,d.region_code,1) on conflict(character_id,region_code) do update set familiarity=least(100,public.exploration_region_state_v262.familiarity+1),updated_at=clock_timestamp();
  insert into public.exploration_journal_v262(character_id,kind,region_code,story_code,title,content,importance) values(v_char,'start',d.region_code,d.story_code,'开始游历 · '||d.title,d.synopsis,1);
  return jsonb_build_object('status','started','run',jsonb_build_object('run_id',v_run.id,'story_code',d.story_code,'region_code',d.region_code,'mode',p_mode,'stage',v_stage,'pending_spirit_stones',0,'insight_gained',0,'node',v_node));
end $$;

create or replace function public.exploration_choose_v262(p_run_id uuid,p_choice_code text)
returns jsonb language plpgsql security definer set search_path='' as $$
declare c jsonb:=public.exploration_context_v262();v_char uuid:=(c->>'character_id')::uuid;v_major int:=(c->>'major_order')::int;s public.exploration_settings_v262%rowtype;x public.exploration_runs_v262%rowtype;d public.exploration_story_defs_v262%rowtype;v_choice jsonb;v_allowed boolean:=false;v_stage int;v_next int;v_final boolean:=false;v_pending bigint;v_gain bigint:=0;v_insight int:=0;v_summary text;v_node jsonb;v_gate int;v_battle jsonb:='{}'::jsonb;v_snapshot jsonb:='{}'::jsonb;v_attack numeric;v_defense numeric;v_vitality numeric;v_ba numeric;v_bd numeric;v_bv numeric;v_player_power numeric;v_enemy_power numeric;v_win_prob numeric;v_won boolean;v_keep int;v_minutes int;v_injury text;v_npc_summary text;v_new_discovery boolean:=false;v_fail boolean:=false;v_risk numeric:=0;
begin
  select * into s from public.exploration_settings_v262 where singleton_id=1;
  select * into x from public.exploration_runs_v262 where id=p_run_id and character_id=v_char for update;if x.id is null or x.status<>'active' then raise exception 'EXPLORATION_RUN_NOT_ACTIVE';end if;
  select * into d from public.exploration_story_defs_v262 where story_code=x.story_code and enabled;if d.story_code is null then raise exception 'EXPLORATION_STORY_NOT_FOUND';end if;
  p_choice_code:=lower(trim(coalesce(p_choice_code,'')));
  for v_choice in select value from jsonb_array_elements(x.current_node->'choices') loop if v_choice->>'code'=p_choice_code then v_allowed:=true;exit;end if;end loop;if not v_allowed then raise exception 'EXPLORATION_CHOICE_INVALID';end if;
  v_stage:=x.stage;v_pending:=x.pending_spirit_stones;
  if p_choice_code='retreat' then
    if v_pending>0 then perform public.tianxu_inventory_adjust_v255(v_char,'spirit_stone',v_pending);end if;
    update public.exploration_runs_v262 set status='retreated',result_summary='你带着已经获得的东西安全离开，没有继续把风险压上去。',resolved_at=clock_timestamp(),updated_at=clock_timestamp() where id=x.id;
    insert into public.exploration_journal_v262(character_id,kind,region_code,story_code,title,content,importance,metadata) values(v_char,'retreat',d.region_code,d.story_code,'见好就收 · '||d.title,'你选择在风险继续扩大前离开。已安全带回旅囊中的'||v_pending||'灵石。',1,jsonb_build_object('stones',v_pending));
    return jsonb_build_object('status','retreated','summary','你安全返回。','settled_spirit_stones',v_pending,'run_id',x.id);
  end if;

  -- 基础见闻与旅囊奖励；真正到账只在安全结束/完成时结算。
  v_insight:=case p_choice_code when 'observe' then 1 when 'record' then 2 when 'greet' then 2 when 'help' then 3 when 'investigate' then 3 when 'track' then 3 when 'comprehend' then 4 when 'mediate' then 4 when 'force' then 4 when 'fight' then 3 when 'harvest_careful' then 2 when 'harvest_greedy' then 2 else 2 end;
  v_gain:=greatest(5,(18*v_major*v_major + d.danger_level*12 + v_stage*7));
  if p_choice_code in('observe','record','greet') then v_gain:=v_gain/3;end if;
  if p_choice_code in('help','investigate','track','comprehend','mediate') then v_gain:=v_gain/2;end if;
  if p_choice_code='harvest_careful' then v_gain:=v_gain;end if;
  if p_choice_code='harvest_greedy' then v_gain:=v_gain*2;v_risk:=0.16+d.danger_level*0.05;end if;
  if p_choice_code='force' then v_gain:=v_gain*2;v_risk:=0.20+d.danger_level*0.06;end if;
  if p_choice_code='resolve_claim' then v_gain:=v_gain*2;v_risk:=0.08+d.danger_level*0.03;end if;
  if p_choice_code='resolve_spare' then v_gain:=v_gain/2;end if;
  if p_choice_code='resolve_leave' then v_gain:=0;end if;

  if p_choice_code='fight' then
    begin execute 'select public.get_my_battle_snapshot_v1()' into v_snapshot;exception when others then v_snapshot:='{}'::jsonb;end;
    v_attack:=coalesce(nullif(v_snapshot->>'attack','')::numeric,100*v_major*v_major);
    v_defense:=coalesce(nullif(v_snapshot->>'defense','')::numeric,80*v_major*v_major);
    v_vitality:=coalesce(nullif(v_snapshot->>'vitality','')::numeric,300*v_major*v_major);
    v_ba:=coalesce(nullif(v_snapshot->>'realm_base_attack','')::numeric,nullif(v_snapshot->>'base_attack','')::numeric,100*v_major*v_major);
    v_bd:=coalesce(nullif(v_snapshot->>'realm_base_defense','')::numeric,nullif(v_snapshot->>'base_defense','')::numeric,80*v_major*v_major);
    v_bv:=coalesce(nullif(v_snapshot->>'realm_base_vitality','')::numeric,nullif(v_snapshot->>'base_vitality','')::numeric,300*v_major*v_major);
    v_player_power:=greatest(1,v_attack+v_defense+v_vitality/4);
    v_enemy_power:=greatest(1,(v_ba+v_bd+v_bv/4)*(0.72+d.danger_level*0.20+greatest(0,v_stage-1)*0.04));
    v_win_prob:=greatest(0.12,least(0.92,v_player_power/(v_player_power+v_enemy_power)+0.05));
    v_won:=random()<v_win_prob;
    v_battle:=jsonb_build_object('enemy_name',case when d.creature_code is not null then replace(split_part(d.title,'·',2),'初见','') else '游历中的敌手' end,'player_power',round(v_player_power,2),'enemy_power',round(v_enemy_power,2),'win_probability',round(v_win_prob,4),'won',v_won,'danger_level',d.danger_level);
    if v_won then
      v_gain:=v_gain*3;v_insight:=v_insight+2;
      update public.exploration_profile_v262 set battles_won=battles_won+1 where character_id=v_char;
      update public.exploration_region_state_v262 set kill_marks=kill_marks+1,beast_pressure=greatest(-100,beast_pressure-2),updated_at=clock_timestamp() where character_id=v_char and region_code=d.region_code;
      v_summary:='你在正面交锋中占了上风。胜利给了你收获，也让这里的生灵开始记住你的做法。';
      perform public.exploration_record_discovery_v262(v_char,d.region_code,d.story_code,d.story_code||':beast','生灵记录 · '||d.title,'你曾在这里真正与它交手并活着带回结果。');
    else
      v_keep=s.defeat_loot_keep_percent;v_pending=floor(v_pending*v_keep/100.0);v_gain:=0;v_fail:=true;
      if v_pending>0 then perform public.tianxu_inventory_adjust_v255(v_char,'spirit_stone',v_pending);end if;
      v_injury:=case when d.danger_level>=4 then 'major' else 'minor' end;v_minutes:=case when v_injury='major' then s.major_injury_minutes else s.minor_injury_minutes end;
      insert into public.exploration_injury_v262(character_id,severity,label,detail,expires_at) values(v_char,v_injury,case when v_injury='major' then '游历重伤' else '游历负伤' end,'你在游历战斗中败下阵来，需要一段时间恢复。',clock_timestamp()+make_interval(mins=>v_minutes)) on conflict(character_id) do update set severity=excluded.severity,label=excluded.label,detail=excluded.detail,expires_at=excluded.expires_at,updated_at=clock_timestamp();
      update public.exploration_profile_v262 set battles_lost=battles_lost+1 where character_id=v_char;
      update public.exploration_runs_v262 set status='failed',pending_spirit_stones=0,last_battle=v_battle,result_summary='你不是它的对手，只能带伤脱离。未安全结算的旅囊损失了一部分，保住的部分已结算。',resolved_at=clock_timestamp(),updated_at=clock_timestamp() where id=x.id;
      insert into public.exploration_journal_v262(character_id,kind,region_code,story_code,title,content,importance,metadata) values(v_char,'defeat',d.region_code,d.story_code,'败退 · '||d.title,'你在游历中败下阵来。保住了部分旅囊并带回，但必须先养伤。',3,v_battle||jsonb_build_object('settled_kept_stones',v_pending,'injury',v_injury));
      return jsonb_build_object('status','defeated','summary','你被对手压制，只能带伤脱离。','battle',v_battle,'settled_spirit_stones',v_pending,'injury',jsonb_build_object('severity',v_injury,'minutes',v_minutes));
    end if;
  elsif v_risk>0 and random()<least(0.65,v_risk) then
    v_keep=s.defeat_loot_keep_percent;v_pending=floor(v_pending*v_keep/100.0);v_fail:=true;if v_pending>0 then perform public.tianxu_inventory_adjust_v255(v_char,'spirit_stone',v_pending);end if;v_injury:=case when d.danger_level>=4 then 'major' else 'minor' end;v_minutes:=case when v_injury='major' then s.major_injury_minutes else s.minor_injury_minutes end;
    insert into public.exploration_injury_v262(character_id,severity,label,detail,expires_at) values(v_char,v_injury,'冒险受伤','你在强行推进探索时触发了本可以避免的危险。',clock_timestamp()+make_interval(mins=>v_minutes)) on conflict(character_id) do update set severity=excluded.severity,label=excluded.label,detail=excluded.detail,expires_at=excluded.expires_at,updated_at=clock_timestamp();
    update public.exploration_runs_v262 set status='failed',pending_spirit_stones=0,result_summary='冒进触发了危险，你带伤撤回并损失部分未结算旅囊，保住的部分已结算。',resolved_at=clock_timestamp(),updated_at=clock_timestamp() where id=x.id;
    insert into public.exploration_journal_v262(character_id,kind,region_code,story_code,title,content,importance,metadata) values(v_char,'risk_fail',d.region_code,d.story_code,'冒进失手 · '||d.title,'你选择了更激进的路线，结果触发危险并负伤撤回。',2,jsonb_build_object('settled_kept_stones',v_pending,'injury',v_injury));
    return jsonb_build_object('status','failed','summary','冒进失败，你带伤返回。','settled_spirit_stones',v_pending,'injury',jsonb_build_object('severity',v_injury,'minutes',v_minutes));
  end if;

  v_pending:=v_pending+greatest(0,v_gain);
  if p_choice_code in('investigate','record','track','comprehend','observe') and (v_stage>=2 or p_choice_code='record') then
    v_new_discovery:=public.exploration_record_discovery_v262(v_char,d.region_code,d.story_code,d.story_code||':stage:'||v_stage,'发现 · '||d.title,coalesce(d.stage_texts->>(v_stage-1),d.synopsis));
  end if;
  if p_choice_code in('help','greet','mediate','resolve_spare') and d.npc_code is not null then
    v_npc_summary:='你在“'||d.title||'”的游历中选择了“'||p_choice_code||'”。这不是人物面板里的按钮，而是一段共同经历。';perform public.exploration_touch_npc_v262(v_char,d,p_choice_code,v_npc_summary);
  end if;
  if p_choice_code='resolve_spare' and d.story_type='beast' then update public.exploration_region_state_v262 set mercy_marks=mercy_marks+1,beast_pressure=least(100,beast_pressure+1),updated_at=clock_timestamp() where character_id=v_char and region_code=d.region_code;end if;

  v_next:=v_stage+1;v_final:=v_next>d.stage_count;
  if v_final then
    if v_pending>0 then perform public.tianxu_inventory_adjust_v255(v_char,'spirit_stone',v_pending);end if;
    update public.exploration_runs_v262 set status='completed',pending_spirit_stones=v_pending,insight_gained=insight_gained+v_insight,last_battle=case when p_choice_code='fight' then v_battle else last_battle end,result_summary='这条游历故事已经走到当前完整结果。',resolved_at=clock_timestamp(),updated_at=clock_timestamp() where id=x.id;
    insert into public.exploration_story_progress_v262(character_id,story_code,current_stage,status,next_realm_order,times_seen,times_completed,last_result,updated_at) values(v_char,d.story_code,d.stage_count,'completed',null,1,1,'completed',clock_timestamp()) on conflict(character_id,story_code) do update set current_stage=d.stage_count,status='completed',next_realm_order=null,times_completed=public.exploration_story_progress_v262.times_completed+1,last_result='completed',updated_at=clock_timestamp();
    insert into public.exploration_profile_v262(character_id,insight,runs_completed) values(v_char,v_insight,1) on conflict(character_id) do update set insight=public.exploration_profile_v262.insight+v_insight,runs_completed=public.exploration_profile_v262.runs_completed+1,updated_at=clock_timestamp();
    insert into public.exploration_journal_v262(character_id,kind,region_code,story_code,title,content,importance,metadata) values(v_char,'story_complete',d.region_code,d.story_code,'完成 · '||d.title,'这段经历已经成为你的正式游历记录。安全带回'||v_pending||'灵石，并获得'||v_insight||'见闻。',case when d.is_cross_realm then 5 else 3 end,jsonb_build_object('stones',v_pending,'insight',v_insight,'choice',p_choice_code));
    return jsonb_build_object('status','completed','summary','这段经历走到了结果。','settled_spirit_stones',v_pending,'insight_gained',v_insight,'battle',v_battle,'story_title',d.title);
  end if;

  v_gate:=coalesce(d.stage_gates[v_next],d.min_major_order);
  if v_gate>v_major then
    if v_pending>0 then perform public.tianxu_inventory_adjust_v255(v_char,'spirit_stone',v_pending);end if;
    update public.exploration_runs_v262 set status='paused',pending_spirit_stones=v_pending,insight_gained=insight_gained+v_insight,last_battle=case when p_choice_code='fight' then v_battle else last_battle end,result_summary='你已经走到当前境界能理解的尽头。突破之后，这条旧缘还会继续。',resolved_at=clock_timestamp(),updated_at=clock_timestamp() where id=x.id;
    insert into public.exploration_story_progress_v262(character_id,story_code,current_stage,status,next_realm_order,times_seen,last_result,updated_at) values(v_char,d.story_code,v_next,'paused',v_gate,1,'realm_gate',clock_timestamp()) on conflict(character_id,story_code) do update set current_stage=v_next,status='paused',next_realm_order=v_gate,last_result='realm_gate',updated_at=clock_timestamp();
    insert into public.exploration_profile_v262(character_id,insight) values(v_char,v_insight) on conflict(character_id) do update set insight=public.exploration_profile_v262.insight+v_insight,updated_at=clock_timestamp();
    insert into public.exploration_journal_v262(character_id,kind,region_code,story_code,title,content,importance,metadata) values(v_char,'realm_pause',d.region_code,d.story_code,'暂别 · '||d.title,'你已经走到当前境界能理解的尽头。达到更高境界后再回来，这件事会继续。',4,jsonb_build_object('next_realm_order',v_gate,'settled_stones',v_pending));
    return jsonb_build_object('status','paused','summary','当前境界只能走到这里。突破后它会继续。','next_realm_order',v_gate,'settled_spirit_stones',v_pending,'insight_gained',v_insight,'battle',v_battle);
  end if;

  v_node:=public.exploration_make_node_v262(d.story_code,v_next);
  update public.exploration_runs_v262 set stage=v_next,pending_spirit_stones=v_pending,insight_gained=insight_gained+v_insight,current_node=v_node,last_battle=case when p_choice_code='fight' then v_battle else last_battle end,updated_at=clock_timestamp() where id=x.id;
  insert into public.exploration_story_progress_v262(character_id,story_code,current_stage,status,next_realm_order,times_seen,last_result,updated_at) values(v_char,d.story_code,v_next,'active',null,1,p_choice_code,clock_timestamp()) on conflict(character_id,story_code) do update set current_stage=v_next,status='active',next_realm_order=null,last_result=p_choice_code,updated_at=clock_timestamp();
  insert into public.exploration_profile_v262(character_id,insight) values(v_char,v_insight) on conflict(character_id) do update set insight=public.exploration_profile_v262.insight+v_insight,updated_at=clock_timestamp();
  insert into public.exploration_journal_v262(character_id,kind,region_code,story_code,title,content,importance,metadata) values(v_char,'step',d.region_code,d.story_code,d.title,'第'||v_stage||'阶段：你选择了“'||coalesce(v_choice->>'label',p_choice_code)||'”。',1,jsonb_build_object('choice',p_choice_code,'pending_stones',v_pending,'new_discovery',v_new_discovery));
  return jsonb_build_object('status','continued','run_id',x.id,'stage',v_next,'pending_spirit_stones',v_pending,'insight_gained_total',x.insight_gained+v_insight,'node',v_node,'battle',v_battle,'new_discovery',v_new_discovery);
end $$;

-- ==================== MORE NATURAL LOCAL FALLBACK ====================
create or replace function public.server_personality_v1(p_context jsonb)
returns jsonb language plpgsql security definer set search_path='' as $$
declare
  v_name text:=coalesce(p_context#>>'{npc,name}','TA');v_action text:=coalesce(p_context->>'action','talk');v_kind text:=coalesce(p_context->>'request_kind','interaction');v_msg text:=left(trim(coalesce(p_context->>'player_message','')),300);
  v_temper text:=lower(coalesce(p_context#>>'{npc,personality,temperament}','steady'));v_mood text:=coalesce(p_context#>>'{life,mood_label}','');v_activity text:=coalesce(p_context#>>'{life,current_activity}','');v_story text:=coalesce(p_context#>>'{active_story,title}','');v_aff int:=coalesce((p_context#>>'{relation,affinity}')::int,0);v_trust int:=coalesce((p_context#>>'{relation,trust}')::int,0);v_rom int:=coalesce((p_context#>>'{relation,romance}')::int,0);v_dialogue text;v_decision text:='neutral';v_hostile boolean;
begin
  v_hostile:=v_msg ~* '(去你妈|你妈的|尼玛|妈的|傻逼|煞笔|蠢货|废物|滚蛋|滚开|操你|草你|艹你|狗东西|贱人|去死)';
  if v_action in('talk:free','message:free') then
    if v_hostile then v_decision:='reject';v_dialogue:=case when v_temper in('fiery','bold','stern') then '“嘴放干净点。再这么说，我就走了。”' when v_temper in('gentle','warm') then '“我可以听你生气，但别拿我撒气。”' else '“够了。这种话我不想再听第二遍。”' end;
    elsif v_msg ~* '(道侣|结为道侣|结成道侣|和我在一起|喜欢我吗)' then
      if v_aff>=65 and v_trust>=60 and v_rom>=45 then v_decision:='defer';v_dialogue:=case when v_temper in('quiet','reserved','cool') then '“……道侣？你要是认真的，就别把这种事当随口一问。等你想清楚了，再当面跟我说一次。”' else '“你问得倒直接。我不是没想过，只是不想这么草率地答应。你先告诉我——为什么是我？”' end;
      elsif v_aff>=25 or v_trust>=25 then v_decision:='defer';v_dialogue:='“道侣？我们还没走到那一步。你要是真有这个念头，就先好好相处，别急着替以后下结论。”';
      else v_decision:='reject';v_dialogue:='“你是不是问得太快了？我们连彼此都还没真正看清，我不会现在答应。”';end if;
    elsif v_msg ~* '(最近|好吗|怎么样|在做什么|忙什么)' then v_dialogue:='“'||case when v_activity<>'' then replace(v_activity,'正在','我最近在')||'。' else '最近没什么大事。' end||case when v_mood<>'' then '今天倒是'||v_mood||'。' else '' end||case when v_story<>'' then '“'||v_story||'”那件事还压在手上。' else '' end||'你呢？”';
    elsif v_msg ~* '(为什么|怎么想|怎么看|觉得)' then v_dialogue:='“你真想听？'||case when v_trust>=50 then '那我就直说，不过你别只挑好听的听。' when v_trust>=20 then '我可以说一点，但有些话还不到时候。' else '我们还没熟到我什么都告诉你的地步。' end||'”';
    elsif length(v_msg)>0 then v_dialogue:=case when v_temper in('bright','bold','free') then '“你这话倒有意思。说具体点，我听着。”' when v_temper in('quiet','reserved','cool') then '“嗯。然后呢？”' when v_temper in('stern','rational') then '“别绕。你真正想问的是什么？”' else '“好，你继续说。”' end;
    else v_dialogue:='“想说什么就说，我在。”';end if;
  elsif v_kind='romance' then v_dialogue:='“这种话我不会随便答。你先把真正想说的说完。”';v_decision='defer';
  elsif v_action like 'gift:%' then v_dialogue:='“你特意挑的？先说说，怎么会想到送我这个。”';
  elsif v_action like 'meeting:%' then v_dialogue:='“走吧。路上慢慢说。”';
  elsif v_action like 'story:%' then v_dialogue:='“你确定要这么做？想清楚了，我就陪你把这一步走完。”';
  elsif v_action like 'inbox:%' then v_dialogue:='“看到了。你这次回得倒快。”';
  else v_dialogue:='“嗯？你想说什么？”';end if;
  return jsonb_build_object('proposal',jsonb_build_object('decision',v_decision,'dialogue',left(v_dialogue,500),'next_goal','按自己的生活与关系继续回应','action_intent','自然回应当前话题','rationale','本地人格兜底只提供人物语言与立场，所有状态仍由服务端审核。'),'engine','server_personality_v1');
exception when others then return jsonb_build_object('proposal',jsonb_build_object('decision','neutral','dialogue','“嗯？你接着说。”','next_goal','保持当前生活','action_intent','等待玩家继续','rationale','最小本地人格兜底'),'engine','server_personality_v1');end $$;

