-- ==================== FINAL GATE ====================
do $gate$
declare v_count int;v_cross int;v_public int;
begin
  select count(*) into v_count from public.exploration_story_defs_v262 where enabled;if v_count<>300 then raise exception 'SQL262_GATE_STORY_COUNT:%',v_count;end if;
  select count(*) into v_cross from public.exploration_story_defs_v262 where enabled and is_cross_realm;if v_cross<>60 then raise exception 'SQL262_GATE_CROSS_STORY_COUNT:%',v_cross;end if;
  if (select count(*) from public.exploration_regions_v262 where enabled)<>8 then raise exception 'SQL262_GATE_REGION_COUNT';end if;
  if to_regprocedure('public.get_exploration_hub_v262()') is null or to_regprocedure('public.exploration_start_v262(text,text)') is null or to_regprocedure('public.exploration_choose_v262(uuid,text)') is null then raise exception 'SQL262_GATE_PLAYER_RPC_MISSING';end if;
  if pg_get_function_result(to_regprocedure('public.tiandao_add_memory_v259(uuid,uuid,text,text,integer,boolean,jsonb)'))<>'void' then raise exception 'SQL262_GATE_TIANDAO_MEMORY_ABI_CHANGED';end if;
  select count(*) into v_public from information_schema.routine_privileges where specific_schema='public' and routine_name in('exploration_record_discovery_v262','exploration_touch_npc_v262','exploration_context_v262','exploration_make_node_v262','server_personality_v1') and grantee in('anon','authenticated','PUBLIC') and privilege_type='EXECUTE';if v_public<>0 then raise exception 'SQL262_GATE_INTERNAL_EXPOSED:%',v_public;end if;
  if not has_function_privilege('authenticated','public.get_exploration_hub_v262()','EXECUTE') or not has_function_privilege('authenticated','public.exploration_start_v262(text,text)','EXECUTE') or not has_function_privilege('authenticated','public.exploration_choose_v262(uuid,text)','EXECUTE') then raise exception 'SQL262_GATE_AUTH_RPC_MISSING';end if;
end
$gate$;

commit;
select jsonb_build_object('sql',262,'revision','R1_JIUXIAO_EXPLORATION_300','gate','SQL262_GATE_PASSED','release','V2.2.0 CACHE134','stories',300,'realm_specific',240,'cross_realm',60,'regions',8,'module','九霄游历V1 / 9境界差异 / 妖兽战斗 / NPC共同经历 / 跨境界因果 / 游历志','edge','需要部署 tiandao-ai CACHE134 R3','next_sql',263) as sql262_install_result;
